import{_ as e,o as d,c as o,a2 as c}from"./chunks/framework.D5wUhsuj.js";const b=JSON.parse('{"title":"Shared: компоненты","description":"","frontmatter":{},"headers":[],"relativePath":"shared/components.md","filePath":"shared/components.md","lastUpdated":1785946763000}'),a={name:"shared/components.md"};function r(n,t,h,i,s,l){return d(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="shared-компоненты" tabindex="-1">Shared: компоненты <a class="header-anchor" href="#shared-компоненты" aria-label="Permalink to &quot;Shared: компоненты&quot;">​</a></h1><p>Каталог: <code>src/shared/components/</code>.</p><p>Общие правила:</p><ul><li>префикс классов <code>gp-*</code>;</li><li>многие принимают prop <code>modify</code> (строка или массив доп. CSS-классов);</li><li>клик у кнопок — нативный <code>@click</code> на корне, отдельного emit обычно нет.</li></ul><hr><h2 id="buttoncomponent" tabindex="-1">ButtonComponent <a class="header-anchor" href="#buttoncomponent" aria-label="Permalink to &quot;ButtonComponent&quot;">​</a></h2><p><strong>Путь:</strong> <code>ButtonComponent/ButtonComponent.vue</code></p><p>Универсальная кнопка с текстом и/или иконками. Базовый UI-примитив.</p><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Prop</th><th>Тип</th><th>Default</th><th>Описание</th></tr></thead><tbody><tr><td><code>text</code></td><td><code>string</code></td><td><code>&#39;&#39;</code></td><td>Текст кнопки</td></tr><tr><td><code>icon</code></td><td><code>Component | string | null</code></td><td><code>null</code></td><td>Единственная иконка (icon-only → класс <code>gp-button_theme_icon</code>)</td></tr><tr><td><code>iconBefore</code></td><td><code>Component | string | null</code></td><td><code>null</code></td><td>Иконка перед текстом (<code>string</code> → <code>&lt;img&gt;</code>)</td></tr><tr><td><code>iconAfter</code></td><td><code>Component | string | null</code></td><td><code>null</code></td><td>Иконка после текста</td></tr><tr><td><code>iconModify</code></td><td><code>string</code></td><td><code>&#39;&#39;</code></td><td>Доп. классы на иконки</td></tr><tr><td><code>type</code></td><td><code>ButtonHTMLAttributes[&#39;type&#39;]</code></td><td><code>&#39;button&#39;</code></td><td>HTML <code>type</code></td></tr><tr><td><code>modify</code></td><td><code>string | string[]</code></td><td><code>&#39;&#39;</code></td><td>Темы / модификаторы на корень</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Блокировка</td></tr><tr><td><code>ariaLabel</code></td><td><code>string</code></td><td>—</td><td><code>aria-label</code></td></tr></tbody></table><h3 id="emits-slots-expose" tabindex="-1">Emits / slots / expose <a class="header-anchor" href="#emits-slots-expose" aria-label="Permalink to &quot;Emits / slots / expose&quot;">​</a></h3><p>Нет. Клик — <code>@click</code> на <code>&lt;button&gt;</code>.</p><h3 id="темы-css" tabindex="-1">Темы CSS <a class="header-anchor" href="#темы-css" aria-label="Permalink to &quot;Темы CSS&quot;">​</a></h3><p><code>gp-button_theme_black</code> - тёмная кнопка</p><p><code>gp-button_theme_white</code> - белая кнопка</p><p><code>gp-button_theme_flat</code> - чистая кнопка (как ссылка)</p><p><code>gp-button_theme_transparent</code> - прозрачная кнопка</p><p><code>gp-button_theme_blur-white</code> - полупрозрачная белая кнопка</p><p><code>gp-button_theme_icon</code> - кнопка с иконкой</p><hr><h2 id="inputcomponent" tabindex="-1">InputComponent <a class="header-anchor" href="#inputcomponent" aria-label="Permalink to &quot;InputComponent&quot;">​</a></h2><p><strong>Путь:</strong> <code>InputComponent/InputComponent.vue</code></p><p>Текстовый input с иконками и опциональной маской (<code>maska</code>). Не v-model: значение через <code>defaultValue</code> + emit <code>input</code>.</p><h3 id="props-1" tabindex="-1">Props <a class="header-anchor" href="#props-1" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Prop</th><th>Тип</th><th>Default</th><th>Описание</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>string</code></td><td>—</td><td><strong>required</strong>, HTML <code>name</code></td></tr><tr><td><code>defaultValue</code></td><td><code>string</code></td><td><code>&#39;&#39;</code></td><td>Значение (<code>:value</code>)</td></tr><tr><td><code>type</code></td><td><code>InputHTMLAttributes[&#39;type&#39;]</code></td><td><code>&#39;text&#39;</code></td><td>Тип input</td></tr><tr><td><code>placeholder</code></td><td><code>string</code></td><td><code>&#39;&#39;</code></td><td>Placeholder</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Disabled</td></tr><tr><td><code>modify</code></td><td><code>string</code></td><td><code>&#39;&#39;</code></td><td>CSS-модификатор</td></tr><tr><td><code>iconBefore</code> / <code>iconAfter</code></td><td><code>Component | string | null</code></td><td><code>null</code></td><td>Иконки слева / справа</td></tr><tr><td><code>maska</code></td><td><code>string</code></td><td><code>&#39;&#39;</code></td><td>Маска <code>v-maska</code></td></tr></tbody></table><h3 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Событие</th><th>Payload</th></tr></thead><tbody><tr><td><code>input</code></td><td><code>string</code> — текущее значение</td></tr></tbody></table><h3 id="методы-внутренние" tabindex="-1">Методы (внутренние) <a class="header-anchor" href="#методы-внутренние" aria-label="Permalink to &quot;Методы (внутренние)&quot;">​</a></h3><p><code>inputHandler(event)</code> — читает <code>event.target.value</code> и эмитит <code>input</code>.</p><hr><h2 id="checkboxcomponent" tabindex="-1">CheckboxComponent <a class="header-anchor" href="#checkboxcomponent" aria-label="Permalink to &quot;CheckboxComponent&quot;">​</a></h2><p><strong>Путь:</strong> <code>CheckboxComponent/CheckboxComponent.vue</code></p><p>Controlled-чекбокс или toggle. Клик только эмитит <code>change</code> — родитель сам меняет <code>checked</code>.</p><h3 id="props-2" tabindex="-1">Props <a class="header-anchor" href="#props-2" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Prop</th><th>Тип</th><th>Default</th><th>Описание</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>string</code></td><td>—</td><td><strong>required</strong>, <code>id</code> / <code>name</code> / <code>for</code></td></tr><tr><td><code>type</code></td><td><code>InputHTMLAttributes[&#39;type&#39;]</code></td><td><code>&#39;checkbox&#39;</code></td><td>Тип input</td></tr><tr><td><code>checked</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Состояние</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Блокировка (клик игнорируется)</td></tr><tr><td><code>modify</code></td><td><code>string</code></td><td><code>&#39;&#39;</code></td><td>CSS-модификатор</td></tr><tr><td><code>icon</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Квадрат с галочкой</td></tr><tr><td><code>toggle</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Switch-тогл</td></tr><tr><td><code>toggleIcon</code></td><td><code>Component | null</code></td><td><code>null</code></td><td>Иконка внутри тогглера</td></tr></tbody></table><h3 id="emits-slots" tabindex="-1">Emits / slots <a class="header-anchor" href="#emits-slots" aria-label="Permalink to &quot;Emits / slots&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Emit <code>change</code></td><td>без payload</td></tr><tr><td>Slot default</td><td>текст лейбла (<code>.gp-checkbox__text</code>)</td></tr></tbody></table><h3 id="методы" tabindex="-1">Методы <a class="header-anchor" href="#методы" aria-label="Permalink to &quot;Методы&quot;">​</a></h3><p><code>checkboxChangeHandler</code> — при <code>!disabled</code> → <code>emit(&#39;change&#39;)</code>.</p><hr><h2 id="errorinput" tabindex="-1">ErrorInput <a class="header-anchor" href="#errorinput" aria-label="Permalink to &quot;ErrorInput&quot;">​</a></h2><p><strong>Путь:</strong> <code>ErrorInput/ErrorInput.vue</code></p><p>Строка ошибки валидации с иконкой.</p><p>Props / emits / expose — нет. <strong>Slot default</strong> — текст ошибки.</p><hr><h2 id="smscodeinput" tabindex="-1">SmsCodeInput <a class="header-anchor" href="#smscodeinput" aria-label="Permalink to &quot;SmsCodeInput&quot;">​</a></h2><p><strong>Путь:</strong> <code>SmsCodeInput/SmsCodeInput.vue</code></p><p>6 отдельных полей OTP: автофокус, backspace, paste. v-model через <code>update:modelValue</code>.</p><h3 id="props-3" tabindex="-1">Props <a class="header-anchor" href="#props-3" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Prop</th><th>Тип</th><th>Описание</th></tr></thead><tbody><tr><td><code>disabled</code></td><td><code>boolean</code></td><td><strong>required</strong> — блокировка полей</td></tr><tr><td><code>error</code></td><td><code>string</code></td><td><strong>required</strong> — текст ошибки; truthy → <code>ErrorInput</code> + <code>is-error</code></td></tr></tbody></table><h3 id="emits-1" tabindex="-1">Emits <a class="header-anchor" href="#emits-1" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Событие</th><th>Payload</th></tr></thead><tbody><tr><td><code>update:modelValue</code></td><td><code>string</code> — склейка 6 символов</td></tr></tbody></table><h3 id="методы-внутренние-1" tabindex="-1">Методы (внутренние) <a class="header-anchor" href="#методы-внутренние-1" aria-label="Permalink to &quot;Методы (внутренние)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Метод</th><th>Поведение</th></tr></thead><tbody><tr><td><code>onInput</code></td><td>Только цифры; фокус на следующее поле</td></tr><tr><td><code>onBackspace</code></td><td>При пустом поле — фокус назад</td></tr><tr><td><code>onPaste</code></td><td>Разбор clipboard → заполнение массива</td></tr><tr><td><code>watch(digits)</code></td><td>Deep → emit <code>update:modelValue</code></td></tr></tbody></table><p>Константа: <code>CODE_LENGTH = 6</code>.</p><hr><h2 id="agreementcomponent" tabindex="-1">AgreementComponent <a class="header-anchor" href="#agreementcomponent" aria-label="Permalink to &quot;AgreementComponent&quot;">​</a></h2><p><strong>Путь:</strong> <code>AgreementComponent/AgreementComponent.vue</code></p><p>Чекбокс согласия с политикой персональных данных. Ссылки открывают <code>PolicyPopup</code>.</p><h3 id="props-4" tabindex="-1">Props <a class="header-anchor" href="#props-4" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Prop</th><th>Тип</th><th>Default</th><th>Описание</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>string</code></td><td><code>&#39;checkbox-agreement&#39;</code></td><td>Название чекбокса</td></tr><tr><td><code>checked</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Состояние</td></tr><tr><td><code>modify</code></td><td><code>string</code></td><td><code>&#39;&#39;</code></td><td>CSS-модификатор</td></tr><tr><td><code>error</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Показать ошибку</td></tr><tr><td><code>errorText</code></td><td><code>string</code></td><td><code>&#39;Обязательное поле&#39;</code></td><td>Текст ошибки</td></tr></tbody></table><h3 id="emits-2" tabindex="-1">Emits <a class="header-anchor" href="#emits-2" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><p><code>change</code> — без payload.</p><h3 id="методы-1" tabindex="-1">Методы <a class="header-anchor" href="#методы-1" aria-label="Permalink to &quot;Методы&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Метод</th><th>Поведение</th></tr></thead><tbody><tr><td><code>agreementChangeHandler</code></td><td>эмитит событие при изменении чекбоска <code>emit(&#39;change&#39;)</code></td></tr><tr><td><code>openPopup(type)</code></td><td>открывает попап с политикой конфиденциальности или обработки персональных данных <code>settingsStore.setPolicyPopupState(true, type)</code> — <code>&#39;policy&#39; | &#39;agreement&#39;</code></td></tr></tbody></table><p><strong>Зависимости:</strong> <code>CheckboxComponent</code>, <code>useSettingsStore</code>.</p><hr><h2 id="policypopup" tabindex="-1">PolicyPopup <a class="header-anchor" href="#policypopup" aria-label="Permalink to &quot;PolicyPopup&quot;">​</a></h2><p><strong>Путь:</strong> <code>PolicyPopup/PolicyPopup.vue</code></p><p>Полноэкранный markdown политики/соглашения. Состояние целиком из <code>settingsStore</code>. Props нет.</p><h3 id="computed-методы" tabindex="-1">Computed / методы <a class="header-anchor" href="#computed-методы" aria-label="Permalink to &quot;Computed / методы&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Имя</th><th>Описание</th></tr></thead><tbody><tr><td><code>isOpen</code></td><td>открыт ли попап <code>getPolicyPopupState</code></td></tr><tr><td><code>showType</code></td><td>тип policy или agreement <code>getTypePolicyPopup</code></td></tr><tr><td><code>source</code></td><td>markdown: политика или соглашение</td></tr><tr><td><code>closeHandler</code></td><td>закрывает попап <code>setPolicyPopupState(false, &#39;policy&#39;)</code></td></tr></tbody></table><p>Рендер: <code>vue-markdown-render</code>. Монтируется в <code>App.vue</code>.</p><hr><h2 id="preloadercomponent" tabindex="-1">PreloaderComponent <a class="header-anchor" href="#preloadercomponent" aria-label="Permalink to &quot;PreloaderComponent&quot;">​</a></h2><p><strong>Путь:</strong> <code>PreloaderComponent/PreloaderComponent.vue</code></p><p>Оверлей «Загрузка...» со сферами фона.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Тип</th><th>Default</th></tr></thead><tbody><tr><td><code>modify</code></td><td><code>string</code></td><td><code>&#39;&#39;</code></td></tr></tbody></table><p>Тема: <code>gp-preloader_theme_black</code> (например в <code>ChatView</code>). Emits / expose — нет.</p><hr><h2 id="backgroundspheres" tabindex="-1">BackgroundSpheres <a class="header-anchor" href="#backgroundspheres" aria-label="Permalink to &quot;BackgroundSpheres&quot;">​</a></h2><p><strong>Путь:</strong> <code>BackgroundSpheres/BackgroundSpheres.vue</code></p><p>Декоративный фон (два SVG-градиента). <code>pointer-events: none</code>.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Тип</th><th>Default</th></tr></thead><tbody><tr><td><code>modify</code></td><td><code>string</code></td><td><code>&#39;&#39;</code></td></tr></tbody></table><h3 id="темы-css-1" tabindex="-1">Темы CSS <a class="header-anchor" href="#темы-css-1" aria-label="Permalink to &quot;Темы CSS&quot;">​</a></h3><p><code>gp-background-spheres_theme_content</code> - фон в визуальном блоке</p><p><code>gp-background-spheres_theme_main-bg</code> - фон в основном блоке</p><p><code>gp-background-spheres_theme_rounded</code> - закругление блока</p><hr><h2 id="tooltipcomponent" tabindex="-1">TooltipComponent <a class="header-anchor" href="#tooltipcomponent" aria-label="Permalink to &quot;TooltipComponent&quot;">​</a></h2><p><strong>Путь:</strong> <code>TooltipComponent/TooltipComponent.vue</code></p><p>Тултип через <code>Teleport</code> в <code>#gigaplan</code>. Hover только при <code>(hover: hover)</code>; клик, Escape, outside click; auto-flip у краёв.</p><h3 id="props-5" tabindex="-1">Props <a class="header-anchor" href="#props-5" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Prop</th><th>Тип</th><th>Default</th><th>Описание</th></tr></thead><tbody><tr><td><code>text</code></td><td><code>string</code></td><td><code>&#39;&#39;</code></td><td>Текст fallback для слота <code>body</code></td></tr><tr><td><code>offset</code></td><td><code>number</code></td><td><code>12</code></td><td>Отступ от активатора (px)</td></tr><tr><td><code>position</code></td><td><code>string</code></td><td><code>&#39;bottom&#39;</code></td><td><code>top</code> | <code>top-end</code> | <code>bottom</code> | <code>bottom-end</code> | <code>left</code> | <code>right</code></td></tr><tr><td><code>modify</code></td><td><code>string</code></td><td><code>&#39;&#39;</code></td><td>Класс на <code>.gp-tooltip__body</code></td></tr><tr><td><code>openOnClick</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Открытие/закрытие по клику</td></tr></tbody></table><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Слот</th><th>Scope</th><th>Описание</th></tr></thead><tbody><tr><td><code>activator</code></td><td><code>{ isOpened }</code></td><td>Триггер</td></tr><tr><td><code>body</code></td><td>—</td><td>Контент; fallback — <code>text</code></td></tr></tbody></table><h3 id="методы-внутренние-2" tabindex="-1">Методы (внутренние) <a class="header-anchor" href="#методы-внутренние-2" aria-label="Permalink to &quot;Методы (внутренние)&quot;">​</a></h3><p><code>showTooltip</code> - открывает тултип</p><p><code>hideTooltip</code> - закрывает тултип</p><p><code>setPosition</code> - устанавливает позицию тултипа</p><p><code>updateTooltipPosition</code> - переуставливает позицию тултипа</p><p><code>bindEvents</code> / <code>removeEvents</code> - навешивает/убирает обрабочики событий</p><p><code>onWindowClick</code> - обрабатывает событие при клике, и закрывает тултип если клик вне тултипа</p><p><code>onKeydown</code> - закрытия тултипа по кнопке Escape</p><p><code>onMouseEnter</code> - событие при наведении мыши на триггер активатор</p><p><code>onMouseLeave</code> - события при убирании мыши с триггера</p><p><code>onClick</code> - событие при клике по триггеру</p><hr><h2 id="tagcomponent" tabindex="-1">TagComponent <a class="header-anchor" href="#tagcomponent" aria-label="Permalink to &quot;TagComponent&quot;">​</a></h2><p><strong>Путь:</strong> <code>TagComponent/TagComponent.vue</code></p><p>Презентационный чип.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Тип</th><th>Описание</th></tr></thead><tbody><tr><td><code>text</code></td><td><code>string</code></td><td>Текст тега</td></tr></tbody></table><p>Emits / slots / expose — нет.</p><hr><h2 id="timercomponent" tabindex="-1">TimerComponent <a class="header-anchor" href="#timercomponent" aria-label="Permalink to &quot;TimerComponent&quot;">​</a></h2><p><strong>Путь:</strong> <code>TimerComponent/TimerComponent.vue</code></p><p>Обратный отсчёт <code>MM:SS</code> / <code>HH:MM:SS</code>. Управление через expose.</p><h3 id="props-6" tabindex="-1">Props <a class="header-anchor" href="#props-6" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Prop</th><th>Тип</th><th>Default</th><th>Описание</th></tr></thead><tbody><tr><td><code>duration</code></td><td><code>number</code></td><td><code>60</code></td><td>Секунды</td></tr><tr><td><code>autoStart</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Старт на <code>onMounted</code></td></tr></tbody></table><h3 id="emits-3" tabindex="-1">Emits <a class="header-anchor" href="#emits-3" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Событие</th><th>Payload</th></tr></thead><tbody><tr><td><code>start</code></td><td>событие при старте</td></tr><tr><td><code>tick</code></td><td>событие при тике таймера</td></tr><tr><td><code>finish</code></td><td>событие при достижении 0</td></tr><tr><td><code>stop</code></td><td>событие при остановке</td></tr></tbody></table><h3 id="expose-методы-состояние" tabindex="-1">Expose (методы / состояние) <a class="header-anchor" href="#expose-методы-состояние" aria-label="Permalink to &quot;Expose (методы / состояние)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Имя</th><th>Сигнатура</th><th>Описание</th></tr></thead><tbody><tr><td><code>start</code></td><td><code>() =&gt; void</code></td><td>Запуск (noop если уже running)</td></tr><tr><td><code>stop</code></td><td><code>() =&gt; void</code></td><td>Остановка + <code>emit(&#39;stop&#39;)</code></td></tr><tr><td><code>reset</code></td><td><code>(newDuration?) =&gt; void</code></td><td>Stop + установка <code>timeLeft</code></td></tr><tr><td><code>restart</code></td><td><code>(newDuration?) =&gt; void</code></td><td><code>reset</code> + <code>start</code></td></tr><tr><td><code>timeLeft</code></td><td><code>Ref&lt;number&gt;</code></td><td>Оставшиеся секунды</td></tr><tr><td><code>isRunning</code></td><td><code>Ref&lt;boolean&gt;</code></td><td>Флаг работы</td></tr></tbody></table><p>Используется в <code>AuthenticationFormCode</code> для повторной отправки SMS.</p><hr><h2 id="speechcomponent" tabindex="-1">SpeechComponent <a class="header-anchor" href="#speechcomponent" aria-label="Permalink to &quot;SpeechComponent&quot;">​</a></h2><p><strong>Путь:</strong> <code>SpeechComponent/SpeechComponent.vue</code></p><p>Тогл «Озвучивание сообщений» → <code>settingsStore</code>.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Тип</th><th>Описание</th></tr></thead><tbody><tr><td><code>modify</code></td><td><code>string</code></td><td>CSS-модификатор (например <code>gp-speech_theme_chat</code>)</td></tr></tbody></table><h3 id="методы-2" tabindex="-1">Методы <a class="header-anchor" href="#методы-2" aria-label="Permalink to &quot;Методы&quot;">​</a></h3><p><code>checkboxChangeHandler</code> → устанавливает глобально должны ли воспроизводиться сообщения голосом <code>settingsStore.setSpeechAll(!speechAll)</code>.</p><p>Emits нет. Внутри: <code>CheckboxComponent</code> с <code>toggle</code> + <code>SoundIcon</code>.</p><hr><h2 id="suggestedoptions" tabindex="-1">SuggestedOptions <a class="header-anchor" href="#suggestedoptions" aria-label="Permalink to &quot;SuggestedOptions&quot;">​</a></h2><p><strong>Путь:</strong> <code>SuggestedOptions/SuggestedOptions.vue</code></p><p>Быстрые ответы ассистента. Клик → сообщение в чат или callback-форма.</p><h3 id="props-7" tabindex="-1">Props <a class="header-anchor" href="#props-7" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Prop</th><th>Тип</th><th>Default</th><th>Описание</th></tr></thead><tbody><tr><td><code>options</code></td><td><code>ISuggestedOption[]</code></td><td>—</td><td><strong>required</strong> — <code>{ title, type }[]</code></td></tr><tr><td><code>modify</code></td><td><code>string | string[]</code></td><td>—</td><td>Классы на <code>.gp-suggested</code></td></tr><tr><td><code>visualKey</code></td><td><code>&#39;default&#39; | &#39;dark&#39;</code></td><td>—</td><td>Тема кнопок</td></tr><tr><td><code>anchorMessageId</code></td><td><code>string</code></td><td>—</td><td>ID сообщения для <code>openCallbackForm</code></td></tr></tbody></table><h3 id="методы-3" tabindex="-1">Методы <a class="header-anchor" href="#методы-3" aria-label="Permalink to &quot;Методы&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Метод</th><th>Поведение</th></tr></thead><tbody><tr><td><code>optionClickHandler(option)</code></td><td><code>type === &#39;contact_request&#39;</code> → открывает форму обратной связи<code>chatStore.openCallbackForm(anchorMessageId)</code>; иначе отправляет быстрый ответ в чат <code>chatStore.sendMessage(option.title)</code></td></tr><tr><td><code>getModify</code></td><td>Классы темы + <code>_theme_callback</code> если type = contact_request</td></tr></tbody></table><p>Кнопки disabled при <code>isThinking</code> / <code>isFrozen</code> (ждёт ответа/проект заморожен). Где используется: <code>ChatMessage</code>, <code>ChatAnswer</code>, <code>EmptyChat</code>.</p><hr><h2 id="newchat" tabindex="-1">NewChat <a class="header-anchor" href="#newchat" aria-label="Permalink to &quot;NewChat&quot;">​</a></h2><p><strong>Путь:</strong> <code>NewChat/NewChat.vue</code></p><p>Кнопка «Новый чат» с проверкой auth, лимита (100) и thinking.</p><h3 id="props-8" tabindex="-1">Props <a class="header-anchor" href="#props-8" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Prop</th><th>Тип</th><th>Default</th><th>Описание</th></tr></thead><tbody><tr><td><code>isCompact</code></td><td><code>boolean</code></td><td><code>false</code></td><td>отображать ли кнопку компактно</td></tr><tr><td><code>modify</code></td><td><code>string</code></td><td><code>&#39;&#39;</code></td><td>Доп. класс кнопки</td></tr></tbody></table><h3 id="computed" tabindex="-1">computed <a class="header-anchor" href="#computed" aria-label="Permalink to &quot;computed&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Имя</th><th>Поведение</th></tr></thead><tbody><tr><td><code>chatsLimitsReached</code></td><td>если пользователь авторизован и больше 100 чатов, то дизейблим кнопку и показываем баннер</td></tr><tr><td><code>chatIsAwaitMessage</code></td><td>активный чат с <code>&lt; 2</code> сообщений и <code>isThinking</code> → disabled</td></tr><tr><td><code>isLoggedIn</code></td><td>авторизован ли пользователь</td></tr><tr><td><code>totalChats</code></td><td>всего чатов у пользователя</td></tr><tr><td><code>activeChat</code></td><td>текущий активный чат</td></tr><tr><td><code>chatIsAwaitMessage</code></td><td>ожидает ли ответ от сервера, если ожидает то блокируем кнопку</td></tr><tr><td><code>isMobile</code></td><td>мобильное ли устройство</td></tr><tr><td><code>isThinking</code></td><td>происходит ли загрузка</td></tr></tbody></table><h3 id="методы-4" tabindex="-1">Методы <a class="header-anchor" href="#методы-4" aria-label="Permalink to &quot;Методы&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Имя</th><th>Поведение</th></tr></thead><tbody><tr><td><code>buttonClickHandler</code></td><td>гость с ≥1 чатом → открывает авторизацию <code>openPopupAuth(true)</code>; иначе создать новый чат <code>tryCreateChat()</code>; на mobile → закрыть сайдбар</td></tr></tbody></table><p><strong>Зависимости:</strong> <code>useAuthStore</code>, <code>useChatStore</code>, <code>useSettingsStore</code>, <code>useSidebarStore</code>, <code>useSidebarPopover</code>. <strong>Где используется:</strong> <code>SidebarHeader</code>, <code>ChatLimits</code>.</p><hr><h2 id="yandexcaptcha" tabindex="-1">YandexCaptcha <a class="header-anchor" href="#yandexcaptcha" aria-label="Permalink to &quot;YandexCaptcha&quot;">​</a></h2><p><strong>Путь:</strong> <code>YandexCaptcha/YandexCaptcha.vue</code></p><p>Обёртка Yandex SmartCaptcha: загрузка скрипта, render, проксирование API.</p><h3 id="props-9" tabindex="-1">Props <a class="header-anchor" href="#props-9" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Prop</th><th>Тип</th><th>Default</th><th>Описание</th></tr></thead><tbody><tr><td><code>siteKey</code></td><td><code>string</code></td><td>—</td><td><strong>required</strong> — клиентский ключ</td></tr><tr><td><code>language</code></td><td><code>&#39;ru&#39; | &#39;en&#39; | …</code></td><td><code>&#39;ru&#39;</code></td><td>Язык виджета (<code>hl</code>)</td></tr><tr><td><code>test</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Тестовый режим</td></tr><tr><td><code>webview</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Режим WebView</td></tr><tr><td><code>invisible</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Невидимая капча (0×0)</td></tr><tr><td><code>shieldPosition</code></td><td><code>string</code></td><td><code>&#39;bottom-right&#39;</code></td><td>Позиция shield</td></tr><tr><td><code>hideShield</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Скрыть shield</td></tr><tr><td><code>loadWidget</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Грузить скрипт на mount</td></tr></tbody></table><h3 id="emits-4" tabindex="-1">Emits <a class="header-anchor" href="#emits-4" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Событие</th><th>Payload</th></tr></thead><tbody><tr><td><code>passExecuteMethod</code></td><td><code>(() =&gt; void) | null</code> — <code>execute</code> при mount, <code>null</code> при unmount</td></tr><tr><td><code>callback</code> / <code>onSuccess</code></td><td><code>token: string</code></td></tr><tr><td><code>onChallengeVisible</code> / <code>onChallengeHidden</code></td><td>—</td></tr><tr><td><code>onNetworkError</code></td><td><code>{ message: string }</code></td></tr><tr><td><code>onJavaScriptError</code></td><td><code>unknown</code></td></tr><tr><td><code>onTokenExpired</code></td><td><code>null</code></td></tr></tbody></table><h3 id="expose-методы" tabindex="-1">Expose (методы) <a class="header-anchor" href="#expose-методы" aria-label="Permalink to &quot;Expose (методы)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Метод</th><th>Сигнатура</th><th>Описание</th></tr></thead><tbody><tr><td><code>execute</code></td><td><code>() =&gt; void</code></td><td>Запуск проверки (invisible)</td></tr><tr><td><code>getResponse</code></td><td><code>() =&gt; string</code></td><td>Текущий токен</td></tr><tr><td><code>reset</code></td><td><code>() =&gt; void</code></td><td>Сброс виджета</td></tr><tr><td><code>destroy</code></td><td><code>() =&gt; void</code></td><td>Удаление виджета</td></tr><tr><td><code>subscribe</code></td><td><code>(event, cb) =&gt; void</code></td><td>Подписка на события SmartCaptcha</td></tr></tbody></table><h3 id="lifecycle-внутреннее" tabindex="-1">Lifecycle (внутреннее) <a class="header-anchor" href="#lifecycle-внутреннее" aria-label="Permalink to &quot;Lifecycle (внутреннее)&quot;">​</a></h3><ol><li><code>loadCaptchaScript</code> → inject <code>captcha.js</code>.</li><li><code>initializeCaptcha</code> → <code>smartCaptcha.render</code> + subscribe.</li><li>Unmount → <code>destroy</code>, <code>passExecuteMethod(null)</code>, удаление script если последний инстанс.</li></ol><p><strong>Где используется</strong>: <code>ChatAction</code> (callback-форма).</p><hr>',166)])])}const u=e(a,[["render",r]]);export{b as __pageData,u as default};
